  if(wideBit(magnitude, dropped - 1) == 1u && (wideAnyBelow(magnitude, dropped - 1) || (kept & 1u) == 1u)) kept++;
  if(kept == 0x1000000u) kept >>= 1, dropped++;  //(rounded up to the next power of two)
  float result = ldexp(float(kept), dropped);
